from collections import Counter
def solve(I):
    bg=Counter(x for row in I for x in row).most_common(1)[0][0]
    cnt=Counter(x for row in I for x in row if x!=bg)
    marker=cnt.most_common(1)[0][0]
    cells=[(r,c,I[r][c]) for r in range(len(I)) for c in range(len(I[0])) if I[r][c]!=bg and I[r][c]!=marker]
    rs=[r for r,c,v in cells]; cs=[c for r,c,v in cells]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    pat={ (r-r0-(r1-r0)//2, c-c0-(c1-c0)//2): I[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1) }  # may include bg
    # include bg cells inside bbox
    pat={}
    dr=(r1-r0)//2; dc=(c1-c0)//2
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            pat[(r-r0-dr,c-c0-dc)]=I[r][c]
    O=[row[:] for row in I]
    H,W=len(I),len(I[0])
    for r in range(H):
        for c in range(W):
            if I[r][c]==marker:
                for (dr2,dc2),v in pat.items():
                    rr,cc=r+dr2,c+dc2
                    if 0<=rr<H and 0<=cc<W: O[rr][cc]=v
    return O
